import{S as n,o as t,c as l,a9 as h,B as k}from"./chunks/framework.DxG24V0C.js";const p="/agentsrc/images/opencode/codex-06-exposure.png",e="/agentsrc/images/opencode/codex-06-hero.png",r="/agentsrc/images/opencode/codex-06-execpolicy.png",d="/agentsrc/images/opencode/codex-06-sandbox.png",y=JSON.parse('{"title":"工具系统与安全沙箱","description":"","frontmatter":{},"headers":[],"relativePath":"codex/06-tools-sandbox.md","filePath":"codex/06-tools-sandbox.md","lastUpdated":1787409644000}'),o={name:"codex/06-tools-sandbox.md"},F=Object.assign(o,{setup(E){const i=[{question:"ToolExposure 的 4 种可见性级别设计的核心目的是什么？",options:["将工具按内部实现和第三方扩展两种来源划分可见性层级","控制工具对模型的初始暴露时机避免过长工具列表污染 prompt","根据工具敏感级别对用户授予差异化的调用权限控制","兼容不同底层模型 API 对工具可见性语义的差异化要求"],correct:1,explanation:"Direct 初始可见，Deferred 初始隐藏通过 tool_search 发现，DirectModelOnly 仅初始列表不进 code-mode，Hidden 只用于 dispatch。Deferred 的设计灵感是避免初始 tool 列表过长、污染模型的 prompt 空间。"},{question:"Codex 的 ExecPolicy 使用 Starlark 语言定义规则（而非 JSON/YAML），这个设计的优势是什么？",options:["Starlark 是 OpenAI 内部工程团队统一使用的标准配置语言","表达力强且开发者熟悉且支持沙箱化执行比 JSON 更灵活","Starlark 的编译执行速度显著快于 JSON 和 YAML 解析器","JSON 和 YAML 格式无法表达网络规则类型的策略配置"],correct:1,explanation:"Starlark 是 Python 的子集，由 Bazel 推广。Codex 用它定义规则：比 JSON/YAML 表达力强（支持变量、条件），比自创 DSL 通用，且 Starlark 本身就是设计成嵌入式语言，天然沙箱化。"},{question:"Claude Code 没有沙箱而 Codex 有完整跨平台沙箱，这个差异反映了两者什么不同的安全假设？",options:["CC 团队判断沙箱功能在当前版本中优先级较低暂不实现","CC 假设可信环境本地使用而 Codex 假设不可信环境默认安全","CC 选择降低开发复杂度刻意省略非核心安全基础设施","CC 的 TypeScript 技术栈在底层技术上无法实现沙箱隔离"],correct:1,explanation:"CC 假设读者在本地开发，自己对自己负责，通过 PreToolUse hooks 让用户自定义拦截。Codex 假设代理可能被部署到 CI/共享环境/远程服务器，必须有默认安全（沙箱/ExecPolicy/进程加固/网络规则）。"},{question:"ReviewDecision::ApprovedExecpolicyAmendment 这个设计体现了什么思想？",options:["每次用户审批操作后必须以弹窗形式再次确认审批结果","用户的一次审批决策可以沉淀为可持久化的 ExecPolicy 规则","该选项表示用户无权修改已设定的 ExecPolicy 规则配置","仅作为用户在误操作后恢复会话的紧急兜底恢复方案"],correct:1,explanation:'用户批准 rm -rf /tmp/* 时，可以选择"以后类似命令自动批准"。这意味着把用户的单个决策"沉淀"成可持久化的 ExecPolicy 规则，一次决策长期生效。CC 没有这个机制，每次都要重新审批。'}];return(g,s)=>{const a=n("Quiz");return t(),l("div",null,[s[0]||(s[0]=h("",150)),k(a,{questions:i})])}}});export{y as __pageData,F as default};
